use vstd::prelude::*;

verus! {
    spec fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool
        requires
            start + sub.len() <= main.len(),
    {
        let mut result = true;
        let len = sub.len();
        for j in 0..len {
            if main[start + j] != sub[j] {
                result = false;
            }
        }
        result
    }

    fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> (result: bool)
        requires
            start + sub.len() <= main.len(),
    ensures
        result == check_match_at(main, sub, start),
    {
        for j in 0..sub.len() {
            if main[start + j] != sub[j] {
                return false;
            }
        }
        true
    }

    fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> (result: bool)
        requires
            sub.len() <= main.len(),
    ensures
        result == (sub.is_empty() || (0..=main.len() - sub.len()).any(|i| check_match_at(main, sub, i))),
    {
        if sub.is_empty() {
            return true;
        }
        
        if sub.len() > main.len() {
            return false;
        }

        for i in 0..=main.len() - sub.len() {
            if check_match_at(main, sub, i) {
                return true;
            }
        }
        
        false
    }
}

